<?php $max=1;foreach($stats['daily'] as $day)$max=max($max,$day['views']); ?>
<section class="panel site-stats-widget" data-days="<?= $stats['days'] ?>"><div class="panel-heading"><div><span class="eyebrow">بازدید سایت</span><h2>رفت‌وآمد در <?= $stats['days'] ?> روز گذشته</h2></div><?= CHtml::link('گزارش کامل ←',array('adminAnalytics/index'),array('class'=>'text-link','data-pjax'=>'1')) ?></div>
<?php if(!$stats['enabled']): ?><p class="flash">ثبت بازدید غیرفعال است؛ آمار قبلی نمایش داده می‌شود.</p><?php endif; ?>
<div class="visit-metrics"><div><small>بازدید امروز</small><strong data-stat="today"><?= number_format($stats['today']['views']) ?></strong><span><?= number_format($stats['today']['visitors']) ?> بازدیدکننده امروز</span></div><div><small>بازدید در این بازه</small><strong data-stat="views"><?= number_format($stats['views']) ?></strong><span>نمایش صفحات سایت</span></div><div><small>مجموع بازدیدکنندگان یکتای روزانه</small><strong data-stat="visitors"><?= number_format($stats['visitors']) ?></strong><span>تخمینی؛ یک نفر در چند روز تکرار می‌شود</span></div></div>
<div class="visit-chart" style="--visit-days:<?= $stats['days'] ?>" role="list" aria-label="بازدید روزانه به وقت تهران"><?php foreach($stats['daily'] as $day): ?><div class="visit-chart-day" role="listitem" tabindex="0" aria-label="<?= CHtml::encode(JalaliDate::format($day['day'],false).'؛ '.$day['views'].' بازدید، '.$day['visitors'].' بازدیدکننده') ?>"><span class="visit-tooltip"><?= CHtml::encode(JalaliDate::format($day['day'],false)) ?> · <?= number_format($day['views']) ?> بازدید</span><span class="visit-chart-track"><span style="height:<?= max(2,round($day['views']/$max*100)) ?>%" class="<?= $day['views']?'':'visit-chart-zero' ?>"></span></span><time datetime="<?= $day['day'] ?>"><?= substr(JalaliDate::format($day['day'],false),5) ?></time></div><?php endforeach; ?></div>
<?php if(!$stats['views']): ?><p class="muted">هنوز بازدیدی در این بازه ثبت نشده است. بازدید مدیران در آمار محاسبه نمی‌شود.</p><?php endif; ?><p class="muted note">شناسه‌ها ناشناس و روزانه‌اند؛ زمان‌ها بر اساس تهران نمایش داده می‌شوند.</p></section>
